{
  "findings": [
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 bucket does not use KMS encryption by default",
      "resource": "aws_s3_bucket.b",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket relies on the default server-side encryption (AES-256) without explicitly configuring SSE-KMS. Using KMS provides better control over key rotation and access auditing."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket versioning is not enabled",
      "resource": "aws_s3_bucket.b",
      "severity": "MEDIUM",
      "explanation": "Versioning is not enabled, which means accidental deletions or overwrites of objects cannot be recovered, increasing data loss risk."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 bucket access logging is not enabled",
      "resource": "aws_s3_bucket.b",
      "severity": "MEDIUM",
      "explanation": "Server access logging is not configured, preventing visibility into who accessed the bucket and what actions were taken, which hinders security auditing."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 bucket Public Access Block is not configured",
      "resource": "aws_s3_bucket.b",
      "severity": "HIGH",
      "explanation": "While the ACL is set to 'private', explicit Public Access Block configuration is missing. This leaves the bucket vulnerable if other policies or misconfigurations inadvertently allow public access."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "b" {
  bucket = "my-tf-test-bucket-ggff"
  acl    = "private"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "aws:kms"
      }
    }
  }

  logging {
    target_bucket = aws_s3_bucket.log_bucket.id
    target_prefix = "log/"
  }
}

resource "aws_s3_bucket_public_access_block" "b" {
  bucket = aws_s3_bucket.b.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Note: A separate log bucket is required for logging. 
# In a real scenario, you would define this resource as well.
resource "aws_s3_bucket" "log_bucket" {
  bucket = "my-tf-test-bucket-ggff-logs"
  acl    = "log-delivery-write"
}
",
  "fix_summary": "Added explicit KMS encryption configuration, enabled versioning, configured server access logging (with a dedicated log bucket), and applied an AWS S3 Bucket Public Access Block resource to prevent unintended public exposure."
}
